        ai, bi = int(a), int(b)
        return (ai > bi) - (ai < bi)
    if a_numeric:
        return -1
    if b_numeric:
        return 1
    return (a > b) - (a < b)


def _compare_versions(a, b):
    a_major, a_minor, a_patch, a_pre = a
    b_major, b_minor, b_patch, b_pre = b

    for ai, bi in ((a_major, b_major), (a_minor, b_minor), (a_patch, b_patch)):
        if ai != bi:
            return (ai > bi) - (ai < bi)

    if a_pre is None and b_pre is None:
        return 0
    if a_pre is None:
        return 1
    if b_pre is None:
